#!/usr/bin/env python3
"""Calibrate ext4/QEMU FLUSH propagation and volatile-write loss on a disposable NBD disk."""
# Some portions generated by Codex
from __future__ import annotations

import argparse
import json
from pathlib import Path
import signal
import sys
from typing import Any

from runner_common import (
    add_seed_iso_builder_argument,
    backend_control,
    copy_and_hash,
    copy_file_exclusive,
    create_fresh_directory,
    create_qcow_overlay,
    create_seed_iso,
    fence_nbd_then_stop_guest,
    guest_qemu_arguments,
    require_executable,
    require_free_tcp_ports,
    require_regular_file,
    resolve_seed_iso_builder,
    sha256_file,
    start_backend,
    start_logged_process,
    stop_process,
    wait_for_path,
    write_json_exclusive,
    write_text_exclusive,
)

SCRIPT_DIR = Path(__file__).resolve().parent
GUEST_DIR = SCRIPT_DIR / "guest"
DATA_BYTES = 64 * 1024 * 1024


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--scratch-root", required=True, type=Path,
                        help="new, non-existing directory for images, logs, and markers")
    parser.add_argument("--repo-root", required=True, type=Path,
                        help="checkout shared read-only with the guest")
    parser.add_argument("--os-base-image", required=True, type=Path,
                        help="provisioned Ubuntu guest qcow2 with Java 25 and ext4 tools including filefrag")
    parser.add_argument("--firmware-code", required=True, type=Path)
    parser.add_argument("--firmware-vars-template", required=True, type=Path)
    parser.add_argument("--qemu", required=True, type=Path)
    parser.add_argument("--qemu-img", required=True, type=Path)
    add_seed_iso_builder_argument(parser)
    parser.add_argument("--port-base", required=True, type=int)
    parser.add_argument("--machine", choices=("virt", "q35"), default="virt")
    parser.add_argument("--accel", default="hvf")
    parser.add_argument("--cpu", default="host")
    parser.add_argument("--smp", type=int, default=4)
    parser.add_argument("--memory-mib", type=int, default=4096)
    parser.add_argument("--phase1-timeout-seconds", type=int, default=240)
    parser.add_argument("--recovery-timeout-seconds", type=int, default=180)
    return parser.parse_args()


def validate_inputs(args: argparse.Namespace) -> dict[str, Any]:
    repo = args.repo_root.expanduser().resolve(strict=True)
    if not repo.is_dir() or not (repo / ".m2_repo").is_dir():
        raise FileNotFoundError("repository and its .m2_repo must exist")
    seed_iso_tool, seed_iso_builder = resolve_seed_iso_builder(args)
    values = {
        "repo_root": repo,
        "backend": require_regular_file(repo / "scripts/lmdb-crashlab/volatile_nbd.py", "checked-in NBD backend"),
        "os_image": require_regular_file(args.os_base_image, "OS base image"),
        "firmware_code": require_regular_file(args.firmware_code, "UEFI code image"),
        "firmware_vars": require_regular_file(args.firmware_vars_template, "UEFI vars template"),
        "qemu": require_executable(args.qemu, "QEMU"),
        "qemu_img": require_executable(args.qemu_img, "qemu-img"),
        "seed_iso_tool": require_executable(seed_iso_tool, seed_iso_builder),
        "seed_iso_builder": seed_iso_builder,
    }
    if not 1 <= args.port_base <= 65534:
        raise ValueError("--port-base must allow both it and its recovery successor")
    require_free_tcp_ports("127.0.0.1", (args.port_base, args.port_base + 1))
    if args.smp < 1 or args.memory_mib < 1024:
        raise ValueError("guest must have at least one CPU and 1024 MiB RAM")
    if args.phase1_timeout_seconds < 1 or args.recovery_timeout_seconds < 1:
        raise ValueError("guest timeouts must be positive")
    return values


def create_blank_image(path: Path, size: int) -> None:
    with path.open("xb") as stream:
        stream.truncate(size)
        stream.flush()
        import os
        os.fsync(stream.fileno())


def parse_events(path: Path) -> list[dict[str, Any]]:
    return [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines() if line.strip()]


def start_guest(inputs: dict[str, Any], args: argparse.Namespace, *, label: str, os_disk: Path,
                vars_file: Path, port: int, seed: Path, serial: Path, results: Path):
    command = guest_qemu_arguments(
        qemu=inputs["qemu"], name=f"rdf4j-crashlab-{label}", machine=args.machine,
        accel=args.accel, cpu=args.cpu,
        smp=args.smp, memory_mib=args.memory_mib, firmware_code=inputs["firmware_code"],
        firmware_vars=vars_file, os_disk=os_disk, data_port=port, seed_iso=seed,
        serial_log=serial, repo_root=inputs["repo_root"], results=results)
    write_json_exclusive(results / f"{label}-qemu-command.json", command)
    return start_logged_process(command, results / f"{label}-qemu.log")


def main() -> int:
    args = parse_args()
    inputs = validate_inputs(args)
    root = create_fresh_directory(args.scratch_root)
    results, qemu_root, nbd_root = root / "results", root / "qemu", root / "nbd"
    data_root = root / "data"
    for directory in (results, qemu_root, nbd_root, data_root):
        directory.mkdir()
    image = data_root / "data.raw"
    create_blank_image(image, DATA_BYTES)
    writer_os = qemu_root / "phase1-os.qcow2"
    recovery_os = qemu_root / "recovery-os.qcow2"
    create_qcow_overlay(inputs["qemu_img"], inputs["os_image"], writer_os,
                        qemu_root / "phase1-os-overlay.log")
    create_qcow_overlay(inputs["qemu_img"], inputs["os_image"], recovery_os,
                        qemu_root / "recovery-os-overlay.log")
    writer_vars, recovery_vars = qemu_root / "phase1-vars.fd", qemu_root / "recovery-vars.fd"
    copy_file_exclusive(inputs["firmware_vars"], writer_vars)
    copy_file_exclusive(inputs["firmware_vars"], recovery_vars)
    writer_seed = create_seed_iso(inputs["seed_iso_tool"], qemu_root, "calibration-phase1",
                                  "boot-calibration-phase1.sh", builder=inputs["seed_iso_builder"])
    recovery_seed = create_seed_iso(inputs["seed_iso_tool"], qemu_root, "calibration-recovery",
                                    "boot-calibration-recovery.sh", builder=inputs["seed_iso_builder"])
    os_hash_before = sha256_file(inputs["os_image"])
    backend_hash_before = sha256_file(inputs["backend"])
    write_json_exclusive(results / "calibration-input-manifest.json", {
        "os_base_image": str(inputs["os_image"]),
        "os_base_image_sha256": os_hash_before,
        "firmware_code_sha256": sha256_file(inputs["firmware_code"]),
        "firmware_vars_template_sha256": sha256_file(inputs["firmware_vars"]),
        "checked_in_backend": str(inputs["backend"]),
        "checked_in_backend_sha256": backend_hash_before,
        "phase1_guest_script_sha256": sha256_file(GUEST_DIR / "boot-calibration-phase1.sh"),
        "recovery_guest_script_sha256": sha256_file(GUEST_DIR / "boot-calibration-recovery.sh"),
        "data_image": str(image),
        "data_image_size_bytes": DATA_BYTES,
        "qemu_data_cache": "writeback plus virtio write-cache=on; backend FLUSH/FUA active",
        "claim_boundary": "ext4/QEMU/volatile NBD guest-device calibration only; not physical host power loss.",
    })

    backend = recovery_backend = qemu = recovery_qemu = None
    control = nbd_root / "phase1-control.sock"
    events = results / "phase1-nbd-events.jsonl"
    failure_path = results / "calibration-runner-failure.txt"
    error: BaseException | None = None
    synced_events: list[dict[str, Any]] = []
    raw_write: dict[str, Any] | None = None
    later_syncs: list[dict[str, Any]] = []
    cut_report: dict[str, Any] | None = None
    preserved: dict[str, Any] | None = None
    recovery_events: list[dict[str, Any]] = []
    report: dict[str, Any] | None = None
    try:
        backend = start_backend(python=Path(sys.executable), backend=inputs["backend"], image=image,
                                control=control, port=args.port_base, events=events,
                                log=results / "phase1-backend.log",
                                command_record=results / "phase1-backend-command.json")
        qemu = start_guest(inputs, args, label="phase1", os_disk=writer_os, vars_file=writer_vars,
                           port=args.port_base, seed=writer_seed,
                           serial=results / "phase1-serial.log", results=results)
        marker = wait_for_path(qemu, [results / "phase1_synced_ready",
                                      results / "calibration-phase1-failed"],
                               args.phase1_timeout_seconds)
        if marker.name != "phase1_synced_ready":
            raise RuntimeError(marker.read_text(errors="replace"))
        synced_events = parse_events(events)
        baseline_syncs = [event for event in synced_events if event.get("event") in ("FLUSH_DONE", "FUA_DONE")]
        if not baseline_syncs:
            raise RuntimeError("synced ext4 probe produced no backend FLUSH_DONE or FUA_DONE event")
        write_text_exclusive(results / "allow_unsynced", "continue\n")
        marker = wait_for_path(qemu, [results / "phase1_unsynced_ready",
                                      results / "calibration-phase1-failed"],
                               60)
        if marker.name != "phase1_unsynced_ready":
            raise RuntimeError(marker.read_text(errors="replace"))
        events_after_raw = parse_events(events)
        raw_offset = int((results / "raw-overwrite-offset").read_text().strip())
        covered = [(index, event) for index, event in enumerate(events_after_raw)
                   if event.get("event") == "WRITE" and
                   event.get("offset", -1) <= raw_offset < event.get("offset", -1) + event.get("length", 0)]
        if not covered:
            raise RuntimeError(f"no acknowledged NBD write covered raw-overwrite offset {raw_offset}")
        write_index, raw_write = covered[-1]
        later_syncs = [event for event in events_after_raw[write_index + 1:]
                       if event.get("event") in ("FLUSH_DONE", "FUA_DONE")]
        if raw_write.get("fua") or later_syncs:
            raise RuntimeError("raw overwrite was followed by a durable FUA/FLUSH acknowledgment")
        write_json_exclusive(results / "calibration-volatile-overwrite-observation.json", {
            "raw_overwrite_offset": raw_offset,
            "acknowledged_write_event": raw_write,
            "durable_events_after_ack_before_cut": later_syncs,
        })
        cut_report = fence_nbd_then_stop_guest(
            qemu,
            lambda: backend_control(Path(sys.executable), inputs["backend"], control, "cut",
                                    "--survival", "drop", "--seed", "20260927"),
        )
        write_json_exclusive(results / "calibration-device-cut.json", cut_report)
        qemu = None
        stop_process(backend, signal.SIGINT)
        backend = None
        preserved_dir = results / "pre-recovery-image"
        preserved_dir.mkdir()
        preserved = copy_and_hash(image, preserved_dir / "data.raw")

        recovery_control = nbd_root / "recovery-control.sock"
        recovery_events_path = results / "recovery-nbd-events.jsonl"
        recovery_backend = start_backend(python=Path(sys.executable), backend=inputs["backend"], image=image,
                                         control=recovery_control, port=args.port_base + 1,
                                         events=recovery_events_path, log=results / "recovery-backend.log",
                                         command_record=results / "recovery-backend-command.json")
        recovery_qemu = start_guest(inputs, args, label="recovery", os_disk=recovery_os,
                                   vars_file=recovery_vars, port=args.port_base + 1,
                                   seed=recovery_seed, serial=results / "recovery-serial.log",
                                   results=results)
        recovery_marker = wait_for_path(recovery_qemu,
                                        [results / "calibration-recovery-done",
                                         results / "calibration-recovery-failed"],
                                        args.recovery_timeout_seconds)
        stop_process(recovery_qemu, signal.SIGKILL)
        recovery_qemu = None
        recovery_events = parse_events(recovery_events_path)
        recovery_output = (results / "calibration-recovery-java-version.txt").read_text(errors="replace")
        recovery_log = (results / "recovery-serial.log").read_text(errors="replace")
        result = "PASS" if recovery_marker.name == "calibration-recovery-done" else "RECOVERY_FAILED"
        durable_events = [event for event in synced_events if event.get("event") in ("FLUSH_DONE", "FUA_DONE")]
        report = {
            "result": result,
            "baseline_probe": "4096 bytes of ASCII A written to a new ext4 file; file and containing directory fsynced before clean unmount",
            "overwrite": "one 4096-byte zero write directly to the allocated ext4 file data block after clean unmount; no subsequent guest sync before device cut",
            "baseline_flush_done_count": sum(event.get("event") == "FLUSH_DONE" for event in durable_events),
            "baseline_fua_done_count": sum(event.get("event") == "FUA_DONE" for event in durable_events),
            "raw_overwrite_ack_before_cut": raw_write,
            "durability_events_after_raw_overwrite_ack": later_syncs,
            "device_cut": cut_report,
            "pre_recovery_image": preserved,
            "recovery_guest_jdk": recovery_output,
            "recovery_log": str(results / "recovery-serial.log"),
            "recovery_backend_event_count": len(recovery_events),
            "recovered_file_oracle": "PASS synced baseline remained exactly 4096 A bytes; volatile raw overwrite was absent"
                if result == "PASS" else "FAIL; see recovery serial and marker artifacts",
            "boundary": "This calibrates guest ext4/QEMU/virtio plus the volatile NBD model; it does not simulate host kernel, APFS, SSD controller, firmware cache, or physical Mac power loss.",
        }
    except BaseException as exc:
        error = exc
        if not failure_path.exists():
            write_text_exclusive(failure_path, type(exc).__name__ + ": " + str(exc) + "\n")
    finally:
        stop_process(qemu, signal.SIGKILL)
        stop_process(recovery_qemu, signal.SIGKILL)
        stop_process(backend, signal.SIGINT)
        stop_process(recovery_backend, signal.SIGINT)

    os_unchanged = sha256_file(inputs["os_image"]) == os_hash_before
    backend_unchanged = sha256_file(inputs["backend"]) == backend_hash_before
    scripts_unchanged = all(
        sha256_file(path) == expected
        for path, expected in (
            (GUEST_DIR / "boot-calibration-phase1.sh",
             json.loads((results / "calibration-input-manifest.json").read_text())["phase1_guest_script_sha256"]),
            (GUEST_DIR / "boot-calibration-recovery.sh",
             json.loads((results / "calibration-input-manifest.json").read_text())["recovery_guest_script_sha256"]),
        )
    )
    if not os_unchanged or not backend_unchanged or not scripts_unchanged:
        error = error or RuntimeError("read-only OS/backend source changed during calibration")
    if error is not None:
        raise error
    assert report is not None
    report["read_only_inputs_unchanged"] = os_unchanged and backend_unchanged and scripts_unchanged
    write_json_exclusive(results / "ext4-crash-calibration-report.json", report)
    print(json.dumps(report, indent=2, sort_keys=True))
    return 0 if report["result"] == "PASS" else 2


if __name__ == "__main__":
    raise SystemExit(main())
